const eye='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg>';
export function renderAuth({register,api,onSuccess,navigate}){
 document.title=(register?'Konto erstellen':'Anmelden')+' · VConnect';
 document.querySelector('#app').innerHTML=`<div class="auth-layout"><section class="auth-story"><a href="/" data-route="/" class="brand"><span class="brand-mark">v<span>✦</span></span>vconnect<span class="brand-period">.</span></a><div class="auth-story-content"><div class="auth-kicker"><span></span> DEINE WELT. BESSER VERNETZT.</div><h1>Gleicher Vibe.<br>Neue <span>Connections.</span></h1><p>Entdecke VTuber, die zu dir passen.<br>Finde Menschen für das, was du liebst.</p><div class="connection-art" aria-hidden="true"><div class="art-grid"></div><div class="art-ring ring-one"></div><div class="art-ring ring-two"></div><div class="art-center">v<span>✦</span></div><div class="art-node node-one">✦</div><div class="art-node node-two">♡</div><div class="art-node node-three">✧</div><div class="art-caption">WENIGER SUCHEN. MEHR CONNECTEN.</div></div><div class="auth-values"><span>✧ VTuber entdecken</span><span>♡ Connections knüpfen</span><span>↗ Collabs finden</span></div></div><div class="auth-story-footer"><span>Für Creator und ihre Community.</span><span>© ${new Date().getFullYear()} VConnect</span></div></section><section class="auth-panel"><div class="auth-topline"><a href="/" data-route="/">← Zurück zu VConnect</a><span>${register?'Schon dabei?':'Neu hier?'} <a href="${register?'/login':'/register'}" data-route="${register?'/login':'/register'}">${register?'Anmelden':'Registrieren'} ↗</a></span></div><main class="auth-main"><div class="auth-form-wrap"><div class="auth-form-icon">${register?'✧':'↗'}</div><span class="eyebrow">${register?'DEINE NÄCHSTE CONNECTION WARTET':'SCHÖN, DASS DU WIEDER DA BIST'}</span><h2>${register?'Dein Start bei VConnect.':'Willkommen zurück.'}</h2><p class="auth-description">${register?'Erstelle dein Konto und finde deinen Platz in der VTuber-Community.':'Melde dich an und bleib mit deiner Community verbunden.'}</p><form id="loginForm" class="auth-form">${register?'<label for="loginName">Anzeigename</label><div class="auth-input"><span>◎</span><input id="loginName" name="name" autocomplete="nickname" required maxlength="40" placeholder="Wie möchtest du heißen?"></div>':''}<label for="loginEmail">E-Mail-Adresse</label><div class="auth-input"><span>@</span><input id="loginEmail" name="email" type="email" autocomplete="email" required maxlength="254" placeholder="du@beispiel.de" autocapitalize="none" spellcheck="false"></div><label for="loginPassword">Passwort</label><div class="auth-input"><span class="lock-symbol"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/><path d="M12 14v3"/></svg></span><input id="loginPassword" name="password" type="password" autocomplete="${register?'new-password':'current-password'}" required minlength="12" maxlength="256" placeholder="${register?'Mindestens 12 Zeichen':'Dein Passwort'}" aria-describedby="passwordHelp"><button id="togglePassword" type="button" aria-label="Passwort anzeigen" aria-pressed="false">${eye}</button></div><div class="password-help" id="passwordHelp">${register?'Mindestens 12 Zeichen. Verwende ein einzigartiges Passwort.':'Dein Konto. Deine Connections.'}</div><div id="loginError" role="alert" class="auth-error" hidden></div><button class="auth-submit" id="loginSubmit" type="submit"><span>${register?'Konto erstellen':'Anmelden'}</span><span>↗</span></button></form><div class="auth-switch">${register?'Du hast bereits ein Konto?':'Du hast noch kein Konto?'} <a href="${register?'/login':'/register'}" data-route="${register?'/login':'/register'}">${register?'Jetzt anmelden':'Jetzt registrieren'}</a></div><div class="auth-divider"></div><a href="/" data-route="/" class="auth-guest">Erst einmal umsehen <span>→</span></a></div></main><div class="auth-bottom"><span class="auth-secure">Dein Zugang zu VConnect.</span><span>VConnect</span></div></section></div>`;
 document.querySelectorAll('[data-route]').forEach(a=>a.onclick=e=>{e.preventDefault();navigate(a.dataset.route)});
 const password=document.querySelector('#loginPassword'),toggle=document.querySelector('#togglePassword');toggle.onclick=()=>{const show=password.type==='password';password.type=show?'text':'password';toggle.setAttribute('aria-label',show?'Passwort verbergen':'Passwort anzeigen');toggle.setAttribute('aria-pressed',String(show))};
 document.querySelector('#loginForm').onsubmit=async e=>{e.preventDefault();const form=e.target,button=document.querySelector('#loginSubmit'),error=document.querySelector('#loginError');button.disabled=true;button.classList.add('loading');button.querySelector('span').textContent=register?'Konto wird erstellt …':'Anmeldung läuft …';error.hidden=true;form.setAttribute('aria-busy','true');const f=new FormData(form);try{const data=await api('/api/'+(register?'register':'login'),{name:f.get('name'),email:f.get('email'),password:f.get('password')});form.reset();onSuccess(data)}catch(err){error.textContent=err.message;error.hidden=false;button.disabled=false;button.classList.remove('loading');button.querySelector('span').textContent=register?'Konto erstellen':'Anmelden';form.setAttribute('aria-busy','false')}};
}
